def fib_mod(n: int, m: int) -> int:
    if m == 1:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 1 % m

    def _fib_pair(k):
        """Returns (F(k), F(k+1)) mod m using fast doubling."""
        if k == 0:
            return (0, 1)
        a, b = _fib_pair(k >> 1)
        # c = F(2k) = F(k) * (2*F(k+1) - F(k))
        # d = F(2k+1) = F(k)^2 + F(k+1)^2
        c = (a * ((2 * b - a) % m)) % m
        d = (a * a + b * b) % m
        if k & 1:
            return (d, (c + d) % m)
        else:
            return (c, d)

    return _fib_pair(n)[0]
